#pragma once

#include "AppEntry.h"

#include <filesystem>
#include <optional>
#include <string>
#include <vector>

namespace apptray
{
	// catalog.json: what the last scan found. Regenerated by every refresh; the user's own
	// choices live in user.json and are never written here.
	struct Catalog
	{
		std::wstring root;       // absolute root of the last scan (informative)
		std::wstring scannedAt;  // UTC time of the last scan
		std::wstring baselineAt; // UTC time of the first scan: apps found then are not "new"
		std::vector<AppEntry> apps;
	};

	std::optional<Catalog> LoadCatalog(const std::filesystem::path& file, std::wstring& error);
	bool SaveCatalog(const std::filesystem::path& file, const Catalog& catalog, std::wstring& error);
}
